    @Test
    public void testRandom_validLengthAndChars() {
        int n = 10;
        char[] chars = {'a', 'b', 'c', '1', '2', '3', '!', '@', '#'};
        String result = Strings.random(n, chars);

        assertNotNull("The generated string should not be null.", result);
        assertEquals("The generated string's length should be n.", n, result.length());

        // Verify that every character in the result is one of the allowed characters
        for (char c : result.toCharArray()) {
            boolean charFoundInAllowedSet = false;
            for (char allowedChar : chars) {
                if (c == allowedChar) {
                    charFoundInAllowedSet = true;
                    break;
                }
            }
            assertTrue("Character '" + c + "' in the generated string must be from the provided 'chars' array.", charFoundInAllowedSet);
        }
    }
